import { Button } from '../Button/Button';
import { FormField } from './FormField';
import type { FormProps, SchemaField, FieldValue } from './types';
import styles from './form.module.css';

export const Form = <T extends SchemaField[]>({
  schema,
  values,
  errors = {},
  onChange,
  onSubmit,
  columns = 1,
  isLoading = false,
  submitLabel = 'Guardar',
  onCancel,
  cancelLabel = 'Cancelar',
  className = '',
}: FormProps<T>) => {
  const fieldsClass = [styles.fields, columns === 2 && styles['cols-2']].filter(Boolean).join(' ');

  return (
    <form className={`${styles.form} ${className}`} onSubmit={onSubmit} noValidate>
      <div className={fieldsClass}>
        {schema.map((field) => (
          <FormField
            key={field.key}
            field={field}
            value={values[field.key] as FieldValue}
            error={errors[field.key]}
            onChange={onChange}
          />
        ))}
      </div>

      <div className={styles.actions}>
        {onCancel && (
          <Button type='button' variant='outline' size='md' onClick={onCancel} disabled={isLoading}>
            {cancelLabel}
          </Button>
        )}
        <Button type='submit' variant='primary' size='md' isLoading={isLoading}>
          {submitLabel}
        </Button>
      </div>
    </form>
  );
};

Form.displayName = 'Form';

import { Input } from '../Input/Input';
import { Textarea } from '../Textarea/Textarea';
import { Checkbox } from '../Checkbox/Checkbox';
import { Select } from '../Select/Select';
import type { SchemaField, FieldValue } from './types';
import styles from './form.module.css';

interface FormFieldProps {
  field: SchemaField;
  value: FieldValue;
  error?: string | string[];
  onChange: (key: string, value: FieldValue) => void;
}

export const FormField = ({ field, value, error, onChange }: FormFieldProps) => {
  const colSpanClass = field.colSpan === 2 ? styles['col-span-2'] : undefined;

  if (field.type === 'checkbox') {
    return (
      <div className={colSpanClass}>
        <Checkbox
          label={field.label}
          checked={Boolean(value)}
          disabled={field.disabled}
          error={typeof error === 'string' ? error : error?.[0]}
          onChange={(e) => onChange(field.key, e.target.checked)}
        />
      </div>
    );
  }

  if (field.type === 'select') {
    return (
      <div className={colSpanClass}>
        <Select
          label={field.label}
          options={field.options}
          value={String(value ?? '')}
          required={field.required}
          disabled={field.disabled}
          helperText={field.helperText}
          error={typeof error === 'string' ? error : error?.[0]}
          onChange={(e) => onChange(field.key, e.target.value)}
        />
      </div>
    );
  }

  if (field.type === 'textarea') {
    return (
      <div className={colSpanClass}>
        <Textarea
          label={field.label}
          value={String(value ?? '')}
          required={field.required}
          disabled={field.disabled}
          placeholder={field.placeholder}
          helperText={field.helperText}
          rows={field.rows}
          error={typeof error === 'string' ? error : error?.[0]}
          onChange={(e) => onChange(field.key, e.target.value)}
        />
      </div>
    );
  }

  // text | email | password | number | date
  return (
    <div className={colSpanClass}>
      <Input
        label={field.label}
        type={field.type}
        value={String(value ?? '')}
        required={field.required}
        disabled={field.disabled}
        placeholder={field.placeholder}
        helperText={field.helperText}
        error={Array.isArray(error) ? error : error ? [error] : undefined}
        onChange={(e) => onChange(field.key, e.target.value)}
      />
    </div>
  );
};
